import { Reactive } from '../dist/index.es.js';
import { ref, nextTick } from 'vue';

class $Session {
  get user() { return ref('ada'); }
  get greeting() { return `hello, ${this.user.value}`; }
}
const Session = Reactive($Session);

const session = new Session();
let fired = 0;
session.$watch(() => session.user.value, () => fired++);

const firstCell = session.user;          // materialized cell
session.user.value = 'grace';
await nextTick();
console.log('watcher fired:', fired);     // 1

session.$stopEffects();

session.user.value = 'linus';            // write into the OLD cell
await nextTick();
console.log('after teardown, watcher fired:', fired);  // still 1 — scope dead

const secondCell = session.user;          // re-touch: a FRESH cell
console.log('cell identity changed:', firstCell !== secondCell);
console.log('fresh value:', session.user.value);        // 'ada' — initializer re-ran
console.log('derivations live again:', session.greeting);

// and the instance can watch again — full second life
let fired2 = 0;
session.$watch(() => session.user.value, () => fired2++);
session.user.value = 'barbara';
await nextTick();
console.log('second-life watcher fired:', fired2);
EOF
