import { ref } from 'vue'
import { Reactive } from 'ivue'

class $Row {
  // GROUND TRUTH — a plain record: survives teardown, costs nothing
  constructor(public record: RowRecord) {}

  // overlay — re-seeds FROM the record on every re-materialization

