// Hover previews for internal links in prose: every page already has
// a 1200x630 image (blog banners, /og/ page banners), and the URL →
// image mapping is deterministic — so one delegated listener gives
// every in-content link a Wikipedia-style preview card with ZERO
// per-page work. Desktop only (hover media); images that don't exist
// simply keep the card hidden (onerror), so nothing needs a manifest.

const SHOW_DELAY_MS = 220;
const CARD_WIDTH = 320;
const CARD_HEIGHT = 168; // 320 / (1200/630)

function previewImageFor(href: string): string | null {
  // strip origin, query, hash, trailing .html
  const url = new URL(href, window.location.origin);
  if (url.origin !== window.location.origin) return null;
  let path = url.pathname.replace(/\.html$/, '');
  if (url.hash && path === window.location.pathname.replace(/\.html$/, ''))
    return null; // same-page anchor
  if (path === '/' || path === '') return '/og-image.png';
  const blogPost = path.match(/^\/blog\/([^/]+)$/);
  if (blogPost) return `/blog/${blogPost[1]}.png`;
  if (path === '/blog/' || path === '/blog') return null; // index has no card
  const slug =
    path.replace(/^\//, '').replace(/\/$/, '/index').replaceAll('/', '-') +
    '.png';
  return `/og/${slug}`;
}

export function installLinkPreviews() {
  // hover is the whole interaction — never on touch devices
  if (!window.matchMedia('(hover: hover) and (pointer: fine)').matches) return;

  const card = document.createElement('div');
  card.className = 'ix-link-preview';
  card.setAttribute('aria-hidden', 'true');
  const image = document.createElement('img');
  image.width = CARD_WIDTH;
  image.height = CARD_HEIGHT;
  image.alt = '';
  card.appendChild(image);
  document.body.appendChild(card);

  let showTimer: number | undefined;
  let currentLink: HTMLAnchorElement | null = null;

  const hide = () => {
    window.clearTimeout(showTimer);
    currentLink = null;
    card.classList.remove('is-visible');
  };

  image.addEventListener('load', () => {
    if (currentLink) card.classList.add('is-visible');
  });
  image.addEventListener('error', hide);

  const position = (link: HTMLAnchorElement) => {
    const rect = link.getBoundingClientRect();
    const margin = 10;
    let left = rect.left + rect.width / 2 - CARD_WIDTH / 2;
    left = Math.max(margin, Math.min(left, window.innerWidth - CARD_WIDTH - margin));
    // prefer above the link; below when there is no room
    let top = rect.top - CARD_HEIGHT - margin;
    if (top < margin) top = rect.bottom + margin;
    card.style.left = `${left}px`;
    card.style.top = `${top}px`;
  };

  document.addEventListener('mouseover', (event) => {
    const link = (event.target as Element | null)?.closest?.(
      '.vp-doc a[href]',
    ) as HTMLAnchorElement | null;
    if (!link || link === currentLink) return;
    hide();
    // links that already show an image (cards, thumbs) need no preview
    if (link.querySelector('img')) return;
    const source = previewImageFor(link.href);
    if (!source) return;
    currentLink = link;
    showTimer = window.setTimeout(() => {
      if (currentLink !== link) return;
      position(link);
      if (image.getAttribute('src') === source) {
        card.classList.add('is-visible');
      } else {
        image.src = source; // 'load' reveals, 'error' hides
      }
    }, SHOW_DELAY_MS);
  });

  document.addEventListener(
    'mouseout',
    (event) => {
      const link = (event.target as Element | null)?.closest?.('.vp-doc a');
      if (link && link === currentLink) hide();
    },
    { passive: true },
  );
  document.addEventListener('scroll', hide, { passive: true });
}

